// Eingabe der Runtime: { query?: string, unread_only?: boolean, limit?: number }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const query = typeof inp.query === 'string' ? inp.query.trim() : '';
const unreadOnly = inp.unread_only === true;
const terms = [];
if (query !== '') terms.push(query);
if (unreadOnly) terms.push('is:unread');
const limit = Number.isInteger(inp.limit) ? Math.max(1, Math.min(50, inp.limit)) : 20;
return [{ json: { q: terms.join(' '), limit, query, unreadOnly } }];

// Stempelt jeden Treffer mit der Konto-Kennung — noetig, weil z.B. drei Gmail-Konten
// strukturell identische Antworten liefern; ohne diesen Stempel liesse sich nach dem
// Merge nicht mehr sagen, aus welchem Konto ein Treffer kam.
//
// Filtert Nicht-Treffer heraus: ein deaktivierter Provider-Knoten (Konto noch nicht
// verbunden) reicht in n8n sein EINGANGSITEM unveraendert durch, statt nichts zu liefern
// — ohne diesen Filter wuerde das zu einem erfundenen "Treffer" ohne echte id (gefunden
// 2026-09-16 beim ersten echten Mehrkonten-Testlauf).
return $input.all()
  .filter((item) => item.json && typeof item.json.id === 'string')
  .map((item) => ({ json: { ...item.json, _account: 'gmail_1' } }));

// Siehe "Tag gmail_1" fuer die Begruendung des Filters.
return $input.all()
  .filter((item) => item.json && typeof item.json.id === 'string')
  .map((item) => ({ json: { ...item.json, _account: 'gmail_2' } }));

// Siehe "Tag gmail_1" fuer die Begruendung des Filters.
return $input.all()
  .filter((item) => item.json && typeof item.json.id === 'string')
  .map((item) => ({ json: { ...item.json, _account: 'gmail_3' } }));

// Siehe "Tag gmail_1" fuer die Begruendung des Filters.
return $input.all()
  .filter((item) => item.json && typeof item.json.id === 'string')
  .map((item) => ({ json: { ...item.json, _account: 'outlook_1' } }));

// Siehe "Tag gmail_1" fuer die Begruendung des Filters.
return $input.all()
  .filter((item) => item.json && typeof item.json.id === 'string')
  .map((item) => ({ json: { ...item.json, _account: 'outlook_2' } }));

// Auf genau die vier erlaubten Angaben je Treffer zusammenschneiden. NIE den Volltext.
// Die id traegt die Konto-Kennung als Praefix (mail-read.json wertet sie aus).
const headers = $input.all().map((item, i) => {
  const m = item.json || {};
  const account = m._account || 'gmail_1';
  const isOutlook = account.startsWith('outlook');
  if (isOutlook) {
    const addr = (m.from && m.from.emailAddress) || {};
    return {
      id: account + ':' + String(m.id || ('msg_' + (i + 1))),
      subject: m.subject || '(kein Betreff)',
      from: addr.name ? (addr.name + ' <' + addr.address + '>') : (addr.address || '(unbekannt)'),
      date: m.receivedDateTime || '',
      summary: (m.bodyPreview || '').toString().slice(0, 240),
      unread: m.isRead === false,
      account
    };
  }
  // Gmails message:getAll liefert Subject/From/To GROSS geschrieben (eigenes Antwortformat,
  // anders als message:get) und kein payload.headers-Array — gefunden 2026-09-16 beim ersten
  // echten Testlauf, vorher zeigte jede Mail "(kein Betreff)"/"(unbekannt)". Kleingeschrieben
  // und payload.headers bleiben als Fallback fuer andere Gmail-Node-Antwortformen stehen.
  const payloadHeaders = (m.payload && m.payload.headers) || [];
  const h = (name) => {
    const hit = payloadHeaders.find((x) => (x.name || '').toLowerCase() === name);
    return hit ? hit.value : '';
  };
  return {
    id: account + ':' + String(m.id || m.messageId || ('msg_' + (i + 1))),
    subject: m.Subject || m.subject || h('subject') || '(kein Betreff)',
    from: m.From || m.from || h('from') || '(unbekannt)',
    date: m.date || h('date') || m.internalDate || '',
    summary: (m.snippet || '').toString().slice(0, 240),
    unread: Array.isArray(m.labels)
      ? m.labels.some((label) => label && label.name === 'UNREAD')
      : Array.isArray(m.labelIds)
        ? m.labelIds.includes('UNREAD')
        : m.unread === true,
    account
  };
});
return [{ json: { messages: headers, count: headers.length } }];
